// Solution for: Three Sum
import java.util.*; public class W42_q3 {public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();int[] a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();Arrays.sort(a);for(int i=0;i<n-2;i++){if(i>0&&a[i]==a[i-1])continue;int l=i+1,r=n-1;while(l<r){int sum=a[i]+a[l]+a[r];if(sum==0){System.out.println(a[i]+" "+a[l]+" "+a[r]);l++;r--;while(l<r&&a[l]==a[l-1])l++;while(l<r&&a[r]==a[r+1])r--;}else if(sum<0)l++;else r--;}}}}
